<template>
<div>
<h2>Кошик покупок</h2>
<p v-if="cardItems.length === 0">Кошик порожній</p>
<ul>
<li v-for="(item, index) in cardItems" :key="index">
<img :src="item.image" :alt="item.name" width="50"/>
{{ item.name }} - {{ item.price }} грн
<button v-on:click="removeItem(index)">Видалити</button>
</li>
</ul>
<p v-if="cardItems.length > 0"> Загальна сума: {{ totalPrice }} грн</p>
</div>
</template>



<script>
import { inject } from "vue";


export default {
    setup() {
        const cardItems = inject("cardItems");
        const totalPrice = inject("totalPrice");
        const removeItem = inject("removeItem");
       
        return {cardItems, totalPrice, removeItem};
    },
};
</script>