<template>
  <div>
    <h1>Пошук товарів</h1>
    <input v-model="searchQuery" placeholder="Введіть назву товару" type="text" />

    <ProductList :products="filteredProducts" />
    <ManageCart />
  </div>
</template>


<script>
import { ref, computed, provide } from 'vue';
import ProductList from '../components/ProductList.vue';
import ManageCart from '../components/ManageCart.vue';

export default {
  name: 'ManageProducts',
  components: {
    ProductList,
    ManageCart
  },
  setup() {
    const searchQuery = ref('');
    const cartItems = ref([]);

     const products = ref ([
        {
          id: 1,
          name: 'Телефон Iphone 11 64 Gb',
          description: 'Популярний телефон',
          price: 9000,
          image: 'https://img.jabko.ua/image/cache/catalog/products/2022/04/081833/iphone11-white-select-2019-1397x1397.jpg.webp'
        },
        {
          id: 2,
          name: 'Ноутбук Lenovo',
          description: 'Гарний Ігровий Ноутбук',
          price: 32000,
          image: 'https://dzvinok.ua/pub/media/catalog/product/l/e/lenovo_ideapad_l340-15irh_gaming_81lk01pmra_-foto1.jpg'
        },
        {
          id: 3,
          name: 'Навушники Samsung Galaxy Buds FE',
          description: 'Бездротові навушники з чистим звуком',
          price: 3500,
          image: 'https://encrypted-tbn1.gstatic.com/shopping?q=tbn:ANd9GcQmCNb4Zw7o6gc3MS33_MFXxfAXtpBGOtTCKNYe0TiBC6YPk3pSMDxNap8brL17UJBPBsRwTFXe7p55aRqm3RV9AMewV3wUR1L4NfV1a50EszDoepmVpMHW'
        },
        {
          id: 4,
          name: 'Геймпад Бездротовий Sony PlayStation 5',
          description: 'Бездротові Геймпад',
          price: 4000,
          image: 'https://i.citrus.world/imgcache/size_800/uploads/shop/1/7/1721209742-opt.webp'
        },
        {
          id: 5,
          name: 'Ігрова консоль Nintendo Switch with Neon Blue and Neon Red Joy-Con',
          description: 'Портативна консоль від Nintendo',
          price: 10000,
          image: 'https://encrypted-tbn0.gstatic.com/shopping?q=tbn:ANd9GcShL2PaQ3gG_SoYg15b7Lxo4xEJFYDYUY9znF4lnuCpTAdcAevPsEwCFFOcYTbBmF-PqPUuTf-27qjU9DF3PmLxB0gfUeTrT7fefYOK89BMTsrSKySEO6Xkxw'
        },
      ]);

    const filteredProducts = computed(() =>
      products.value.filter(product =>
        product.name.toLowerCase().includes(searchQuery.value.toLowerCase())
      )
    );

    const totalPrice = computed(() =>
      cartItems.value.reduce((sum, item) => sum + item.price, 0)
    );

    function addToCart(product) {
      cartItems.value.push(product);
    }

    function removeItem(index) {
      cartItems.value.splice(index, 1);
    }

    provide('cartItems', cartItems);
    provide('totalPrice', totalPrice);
    provide('addToCart', addToCart);
    provide('removeItem', removeItem);

    return {
      searchQuery,
      filteredProducts
    };
  }
}
</script> 